INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-tuition-phd-english', 'CN', 'cost', 'tuition', 'NJUST tuition, English-taught Doctoral', 44200, NULL, 'CNY', 'year', 'NJUST international doctoral students, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', 'Doctoral programs in Chinese: CNY 36,000/Year (Approx. USD 5,050/Year) ▪ Doctoral programs in English: CNY 44,200/Year (Approx. USD 6,200/Year)', 'VERIFIED', '2026-10-25', NULL, '');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-accommodation-master', 'CN', 'cost', 'accommodation', 'NJUST dormitory, Master''s (quad room)', 4000, NULL, 'CNY', 'year', 'NJUST Master''s students, on-campus quad room, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', 'Accommodation Fee: ▪ Master program: CNY 4,000/year (on campus dormitory with a quad room) ▪ Doctoral program: CNY 9,000/year (on campus dormitory with a double room)', 'VERIFIED', '2026-10-25', NULL, 'Doctoral double room 9,000 CNY/year. Electricity approx. 1,000 CNY/year extra.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-meals', 'CN', 'cost', 'living', 'NJUST meal budget estimate', 20000, NULL, 'CNY', 'year', 'NJUST international postgraduates, Nanjing, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', 'Other Estimated Expenses: ▪ Electricity: Approx. CNY 1,000/year ▪ Textbook Fee: Approx. CNY 1,000/year ▪ Meal Budget: Approx. CNY 20,000/year', 'OFFICIAL_ESTIMATE', '2026-10-25', NULL, 'Textbooks approx. 1,000 CNY/year; electricity approx. 1,000 CNY/year.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-application-fee', 'CN', 'cost', 'application', 'NJUST application fee', 500, NULL, 'CNY', 'once', 'NJUST international postgraduate applications, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', 'Application Fee: CNY 500 (Payment in the application system, non-refundable once paid)', 'VERIFIED', '2026-10-25', NULL, '');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('cn-njust-proof-of-funds', 'CN', 'proof_of_funds', 'living', 'Financial statement required (no minimum stated)', NULL, NULL, 'CNY', 'once', 'NJUST international postgraduate application, 2026 intake', 'Nanjing University of Science and Technology (NJUST) School of International Education', 'https://study.njust.edu.cn/74/79/c4398a357497/page.htm', '10. Financial Statement: Proof of sufficient funds (e.g., bank statement, sponsor''s income certificate or guarantee letter).', 'VERIFIED', '2026-10-25', '["bank statement","sponsor''s income certificate","guarantee letter"]', 'Requirement confirmed; no minimum amount stated. A sensible planner proxy is first-year tuition + accommodation + insurance, but that is NOT an official figure.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('pk-hec-degree-attestation', 'PK', 'cost', 'documents', 'HEC degree/transcript attestation (per document)', 3000, NULL, 'PKR', 'once', 'HEC online e-attestation of degree, transcript, provisional certificate or HEC equivalence letter, current', 'Higher Education Commission (HEC) Pakistan', 'https://www.hec.gov.pk/english/services/students/DAS/Pages/Degree-Attestation.aspx', 'The attestation fee is Rs. 3,000 per document (degree, transcript, provisional certificate, or HEC equivalence letter).', 'VERIFIED', '2026-10-25', NULL, 'Per document - multiply by number of documents (e.g. degree + transcript = 6,000). Non-refundable if wrong selection. Needed for Master''s/PhD applicants.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('pk-ibcc-attestation', 'PK', 'cost', 'documents', 'IBCC attestation of SSC/HSSC certificate (per original)', 1200, NULL, 'PKR', 'once', 'IBCC standard attestation (without express service) of original certificate/DMC, current', 'Inter Boards Coordination Commission (IBCC)', 'https://ibcc.edu.pk/faqs/attestation-faqs/', 'What is the fee for obtaining standard IBCC attestation (without express service)? … Original Certificate/DMC Fee: PKR 1200 each', 'VERIFIED', '2026-10-25', NULL, 'Per document. Needed for Bachelor''s applicants (Matric/FSc). Express service costs more (not fetched).');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('pk-ibcc-equivalence-foreign', 'PK', 'cost', 'documents', 'IBCC equivalence certificate, foreign qualification (e.g. O/A Levels)', 6000, NULL, 'PKR', 'once', 'IBCC equivalence of foreign qualifications (O/A Levels, American HSD, IB etc.), current', 'Inter Boards Coordination Commission (IBCC)', 'https://ibcc.edu.pk/faqs/equivalence-faqs/', 'The equivalence fee for foreign qualifications is Rs. 6000 each, while for local qualifications, it is Rs. 4000 each.', 'VERIFIED', '2026-10-25', NULL, 'Per certificate. Urgent O/A Level equivalence: Rs 12,000 each. Only O/A-Level-type students need this before IBCC attestation. Cached copy dated 2026-10-25.');
INSERT INTO cost_references (id, country, kind, category, label, amount, amount_max, currency, unit, applies_to, authority, source_url, excerpt, status, checked_at, evidence_types, notes) VALUES ('pk-mofa-apostille-educational', 'PK', 'cost', 'documents', 'MOFA apostille, educational document (per document)', 3000, NULL, 'PKR', 'once', 'Ministry of Foreign Affairs apostille of educational documents, current (fee revised w.e.f. 8 July 2024 per MOFA consular page)', 'Ministry of Foreign Affairs (MOFA) Pakistan - Apostille portal', 'https://apostille.mofa.gov.pk/fee-structure', 'Document Type Amount Personal Document Rs 3,000 Legal Document Rs 4,500 Educational Document Rs 3,000', 'VERIFIED', '2026-10-25', NULL, 'Per document. Italy (Islamabad) requires Pakistani documents to bear an Apostille; also the NADRA FRC. The 8 July 2024 revision date comes from a search snippet of mofa.gov.pk, not scraped.');
